import{_ as r,c as t,o as a,ah as l}from"./chunks/framework.l36K22_3.js";const d=JSON.parse('{"title":"新手向：Vue 2.0 的建议学习顺序","description":"","frontmatter":{"title":"新手向：Vue 2.0 的建议学习顺序"},"headers":[],"relativePath":"knowledge/study/how-to-learn-vue.md","filePath":"knowledge/study/how-to-learn-vue.md","lastUpdated":1788862678000}'),o={name:"knowledge/study/how-to-learn-vue.md"};function i(p,e,n,u,s,c){return a(),t("div",null,e[0]||(e[0]=[l('<blockquote><p>注：2.0 已经有 <a href="https://cn.vuejs.org" target="_blank" rel="noreferrer">中文文档</a> 。如果对自己英文有信心，也可以直接阅读 <a href="https://vuejs.org" target="_blank" rel="noreferrer">英文文档</a>。 此指南仅供参考，请根据自身实际情况灵活调整。 欢迎转载，请注明出处。</p></blockquote><h2 id="起步" tabindex="-1">起步 <a class="header-anchor" href="#起步" aria-label="Permalink to &quot;起步&quot;">​</a></h2><ol><li><p>扎实的 JavaScript / HTML / CSS 基本功。这是前置条件。</p></li><li><p>通读官方教程 (guide) 的基础篇。不要用任何构建工具，就只用最简单的 &lt;script&gt;，把教程里的例子模仿一遍，理解用法。<strong>不推荐上来就直接用 vue-cli 构建项目，尤其是如果没有 Node/Webpack 基础。</strong></p></li><li><p>照着官网上的示例，自己想一些类似的例子，模仿着实现来练手，加深理解。</p></li><li><p>阅读官方教程进阶篇的前半部分，到『自定义指令 (Custom Directive) 』为止。着重理解 Vue 的响应式机制和组件生命周期。『渲染函数（Render Function)』如果理解吃力可以先跳过。</p></li><li><p>阅读教程里关于路由和状态管理的章节，然后根据需要学习 vue-router 和 vuex。同样的，先不要管构建工具，以跟着文档里的例子理解用法为主。</p></li><li><p>走完基础文档后，如果你对于基于 Node 的前端工程化不熟悉，就需要补课了。下面这些严格来说并不是 Vue 本身的内容，也不涵盖所有的前端工程化知识，但对于大型的 Vue 工程是前置条件，也是合格的『前端工程师』应当具备的知识。</p></li></ol><h2 id="前端生态-工程化" tabindex="-1">前端生态/工程化 <a class="header-anchor" href="#前端生态-工程化" aria-label="Permalink to &quot;前端生态/工程化&quot;">​</a></h2><ol><li><p>了解 JavaScript 背后的规范，ECMAScript 的历史和目前的规范制定方式。学习 ES2015/16 的新特性，理解 ES2015 modules，适当关注<a href="https://github.com/tc39/proposals" target="_blank" rel="noreferrer">还未成为标准的提案</a>。</p></li><li><p>学习命令行的使用。建议用 Mac。</p></li><li><p>学习 Node.js 基础。<strong>建议使用 <a href="https://github.com/creationix/nvm" target="_blank" rel="noreferrer">nvm</a> 这样的工具来管理机器上的 Node 版本，并且将 npm 的 registry 注册表配置为<a href="https://npm.taobao.org" target="_blank" rel="noreferrer">淘宝的镜像源</a>。</strong>至少要了解 npm 的常用命令，npm scripts 如何使用，语义化版本号规则，CommonJS 模块规范（了解它和 ES2015 Modules 的异同），Node 包的解析规则，以及 Node 的常用 API。应当做到可以自己写一些基本的命令行程序。注意最新版本的 Node (6+) 已经支持绝大部分 ES2015 的特性，可以借此巩固 ES2015。</p></li><li><p>了解如何使用 / 配置 Babel 来将 ES2015 编译到 ES5 用于浏览器环境。</p></li><li><p>学习 Webpack。Webpack 是一个极其强大同时也复杂的工具，作为起步，理解它的『一切皆模块』的思想，并基本了解其常用配置选项和 loader 的概念/使用方法即可，比如如何搭配 Webpack 使用 Babel。学习 Webpack 的一个挑战在于其本身文档的混乱，建议多搜索搜索，应该还是有质量不错的第三方教程的。英文好的建议阅读 <a href="https://webpack.js.org/guides/getting-started/" target="_blank" rel="noreferrer">Webpack 2.0 的文档</a>。</p></li></ol><h2 id="vue-进阶" tabindex="-1">Vue 进阶 <a class="header-anchor" href="#vue-进阶" aria-label="Permalink to &quot;Vue 进阶&quot;">​</a></h2><ol><li><p>有了 Node 和 Webpack 的基础，可以通过 vue-cli 来搭建基于 Webpack ，并且支持单文件组件的项目了。建议用 webpack-simple 这个模板开始，并阅读官方教程进阶篇剩余的内容以及 <a href="https://vue-loader.vuejs.org" target="_blank" rel="noreferrer">vue-loader 的文档</a>，了解一些进阶配置。有兴趣的可以自己亲手从零开始搭一个项目加深理解。</p></li><li><p>根据 <a href="https://github.com/vuejs/vue-hackernews-2.0" target="_blank" rel="noreferrer">例子</a> 尝试在 Webpack 模板基础上整合 vue-router 和 vuex</p></li><li><p>深入理解 Virtual DOM 和『渲染函数 (Render Functions)』这一章节（可选择性使用 JSX)，理解模板和渲染函数之间的对应关系，了解其使用方法和适用场景。</p></li><li><p>（可选）根据需求，了解服务端渲染的使用（需要配合 Node 服务器开发的知识）。其实更重要的是理解它所解决的问题并搞清楚你是否需要它。</p></li><li><p>阅读开源的 Vue 应用、组件、插件源码，自己尝试编写开源的 Vue 组件、插件。</p></li><li><p>参考 <a href="https://github.com/vuejs/vue/blob/dev/.github/CONTRIBUTING.md#development-setup" target="_blank" rel="noreferrer">贡献指南</a> 阅读 Vue 的源码，理解内部实现细节。（需要了解 <a href="https://flow.org" target="_blank" rel="noreferrer">Flow</a>）</p></li><li><p>参与 Vue GitHub issue 的定位 -&gt; 贡献 PR -&gt; 加入核心团队 -&gt; 升任 CTO -&gt; 迎娶白富美...（误</p></li></ol><br> &gt; 转自：[尤大大的新手向：Vue 2.0 的建议学习顺序](https://zhuanlan.zhihu.com/p/23134551) ',9)]))}const b=r(o,[["render",i]]);export{d as __pageData,b as default};
